<?php $e=static fn(mixed $value):string=>App\Core\View::e($value); ?>
<section><div class="section-heading"><div><p class="eyebrow">Ambiente protegido</p><h1>Simulações internas</h1><p>Cenários separados. Nunca alteram partidas, tabelas ou documentos oficiais.</p></div><a class="button" href="<?= $e(App\Core\Config::url('/admin/simulacoes/nova')) ?>">Novo cenário</a></div><?php if($message): ?><p class="success"><?= $e($message) ?></p><?php endif; ?><div class="table-wrap"><table><thead><tr><th>Cenário</th><th>Campeonato</th><th>Fase</th><th>Partidas</th><th>Status</th><th>Autor</th><th></th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><a href="<?= $e(App\Core\Config::url('/admin/simulacoes/'.$item['id'])) ?>"><?= $e($item['name']) ?></a></td><td><?= $e($item['championship_name']) ?></td><td><?= $e($item['phase_name']) ?></td><td><?= (int)$item['matches_count'] ?></td><td><?= $e($item['status']==='archived'?'Arquivado':'Ativo') ?></td><td><?= $e($item['author_name']) ?></td><td><a href="<?= $e(App\Core\Config::url('/admin/simulacoes/'.$item['id'])) ?>">Abrir</a></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="7">Nenhum cenário salvo.</td></tr><?php endif; ?></tbody></table></div></section>
